package io.knowledgebrain.integration;
import java.time.*;import java.util.*;import tools.jackson.databind.JsonNode;
/** Uses the existing fixed HTTPS, bounded-body, no-redirect/no-credential GitHub transport. */
final class GitHubWorkClient {
 record Item(String externalId,long number,String title,String state,String authorLogin,Boolean draft,String createdAt,String updatedAt,String closedAt,String url){}
 record Batch(GitHubClient.Repository repository,String kind,List<Item> items,int scannedCount,boolean possiblyMore){}
 private final GitHubClient http;GitHubWorkClient(GitHubClient http){this.http=http;}
 static String kind(String kind){if(!Set.of("ISSUE","PULL_REQUEST").contains(kind))throw GitHubRules.bad();return kind;}
 Batch fetch(GitHubClient.Repository repo,String kind){kind(kind);String leaf=kind.equals("ISSUE")?"issues":"pulls";return parse(repo,kind,http.get("/repos/"+repo.fullName()+"/"+leaf+"?state=all&sort=updated&direction=desc&per_page=20"));}
 static String time(JsonNode n){if(!n.isString())throw GitHubClient.unavailable();String v=Instant.parse(n.asString()).toString();if(v.length()>40)throw GitHubClient.unavailable();return v;}
 static Batch parse(GitHubClient.Repository repo,String kind,JsonNode raw){kind(kind);try{if(raw==null||!raw.isArray()||raw.size()>20)throw GitHubClient.unavailable();var rows=new ArrayList<Item>();var ids=new HashSet<String>();var numbers=new HashSet<Long>();for(var n:raw){if(!n.isObject())throw GitHubClient.unavailable();if(kind.equals("ISSUE")&&n.has("pull_request")){if(!n.path("pull_request").isObject())throw GitHubClient.unavailable();continue;}if(!n.path("id").isIntegralNumber()||!n.path("id").canConvertToLong()||n.path("id").asLong()<1||!n.path("number").isIntegralNumber()||!n.path("number").canConvertToLong()||n.path("number").asLong()<1||n.path("number").asLong()>9007199254740991L||!n.path("title").isString()||!n.path("state").isString()||!Set.of("open","closed").contains(n.path("state").asString()))throw GitHubClient.unavailable();String external=Long.toString(n.path("id").asLong());long number=n.path("number").asLong();if(!ids.add(external)||!numbers.add(number))throw GitHubClient.unavailable();String title=GitHubRules.text(n.path("title").asString(),500,true),state=n.path("state").asString().toUpperCase(Locale.ROOT),created=time(n.path("created_at")),updated=time(n.path("updated_at")),closed=n.path("closed_at").isNull()?null:time(n.path("closed_at"));if(Instant.parse(updated).isBefore(Instant.parse(created))||state.equals("OPEN")!=(closed==null)||closed!=null&&Instant.parse(closed).isBefore(Instant.parse(created)))throw GitHubClient.unavailable();Boolean draft=null;if(kind.equals("PULL_REQUEST")){if(!n.path("draft").isBoolean())throw GitHubClient.unavailable();draft=n.path("draft").asBoolean();}String author=null;if(!n.path("user").isNull()){if(!n.path("user").path("login").isString())throw GitHubClient.unavailable();author=n.path("user").path("login").asString();if(!author.matches("[A-Za-z0-9-]+(?:\\[bot\\])?")||author.length()>100)throw GitHubClient.unavailable();}String url="https://github.com/"+repo.fullName()+"/"+(kind.equals("ISSUE")?"issues":"pull")+"/"+number;if(!n.path("html_url").isString()||!url.equals(n.path("html_url").asString()))throw GitHubClient.unavailable();rows.add(new Item(external,number,title,state,author,draft,created,updated,closed,url));}return new Batch(repo,kind,List.copyOf(rows),raw.size(),raw.size()==20);}catch(RuntimeException e){throw GitHubClient.unavailable();}}
}
